\begin{tikzpicture}[line cap=round,line join=round,>=stealth,font=\sffamily\small]
% flat sheet hint
\draw[thin,dashed,gray] (-3.2,-0.35) rectangle (3.2,3.4);
\node[font=\footnotesize,gray] at (2.4,-0.55) {flat sheet};
