}
\node[font=\footnotesize] at (2.2,-0.2) {mirror};
% normal
\draw[dashed,thick] (0,0)--(0,3.0);
\node[font=\footnotesize] at (0.55,2.85) {normal};
% incident
\draw[->,thick] (-2.5,2.4)--(0,0);
\node[font=\footnotesize] at (-2.6,2.65) {incident};
% reflected
\draw[->,thick] (0,0)--(2.5,2.4);
\node[font=\footnotesize] at (2.6,2.65) {reflected};
\fill (0,0) circle (1.5pt);
\node[font=\footnotesize] at (0.25,-0.35) {O};
